// Regenerates src/lib/airports-data.ts and src/lib/airlines-data.ts from the
// organiser CSVs.
//   node scripts/gen-airports.mjs ../../data/airports.csv ../../data/airlines.csv
// The CSVs (data/ is git-ignored) are airports.csv with IATA_CODE, AIRPORT,
// CITY, STATE, ..., LATITUDE, LONGITUDE and airlines.csv with IATA_CODE,
// AIRLINE. Only codes, names and positions are kept, so the generated files
// stay small and the app needs no data fetch at run time.
import { readFileSync, writeFileSync } from "node:fs";

const [input, airlinesInput] = process.argv.slice(2);
if (!input || !airlinesInput) {
  console.error("usage: node scripts/gen-airports.mjs <airports.csv> <airlines.csv>");
  process.exit(1);
}

/** Splits one CSV line, honouring double-quoted fields. */
function cells(line) {
  const out = [];
  let cur = "";
  let quoted = false;
  for (const ch of line) {
    if (ch === '"') quoted = !quoted;
    else if (ch === "," && !quoted) {
      out.push(cur);
      cur = "";
    } else cur += ch;
  }
  out.push(cur);
  return out;
}

/** Reads a CSV into its rows and a column lookup that fails on a missing name. */
function table(path) {
  const [head, ...lines] = readFileSync(path, "utf8").split(/\r?\n/).filter(Boolean);
  const cols = cells(head);
  const col = (name) => {
    const i = cols.indexOf(name);
    if (i === -1) throw new Error(`Missing column ${name} in: ${head}`);
    return i;
  };
  return { rows: lines.map(cells), col };
}

const airports = table(input);
const [iCode, iName, iCity, iState, iLat, iLon] = ["IATA_CODE", "AIRPORT", "CITY", "STATE", "LATITUDE", "LONGITUDE"].map(airports.col);

const rows = [];
const places = [];
for (const c of airports.rows) {
  const code = c[iCode]?.trim();
  if (!code) continue;
  // An airport without a position still has a name.
  places.push([code, c[iName].trim(), c[iCity].trim(), c[iState].trim()]);
  const lat = Number.parseFloat(c[iLat]);
  const lon = Number.parseFloat(c[iLon]);
  if (Number.isNaN(lat) || Number.isNaN(lon)) continue;
  rows.push([code, Math.round(lat * 1000) / 1000, Math.round(lon * 1000) / 1000]);
}
rows.sort((a, b) => a[0].localeCompare(b[0]));
places.sort((a, b) => a[0].localeCompare(b[0]));

const body = rows.map(([code, lat, lon]) => `${code}:[${lat},${lon}]`).join(",");
const placeBody = places.map(([code, ...p]) => `${code}:${JSON.stringify(p)}`).join(",");
writeFileSync(
  new URL("../src/lib/airports-data.ts", import.meta.url),
  `// Generated by scripts/gen-airports.mjs from data/airports.csv. Do not edit.\n` +
    `/** IATA code to [latitude, longitude]. */\n` +
    `export const AIRPORT_POSITIONS: Record<string, [number, number]> = {${body}};\n` +
    `/** IATA code to [airport name, city, state]. */\n` +
    `export const AIRPORT_PLACES: Record<string, [string, string, string]> = {${placeBody}};\n`,
);
console.log(`wrote ${rows.length} airport positions and ${places.length} airport names`);

const airlines = table(airlinesInput);
const [iAirline, iAirlineName] = ["IATA_CODE", "AIRLINE"].map(airlines.col);
const carriers = airlines.rows
  .filter((c) => c[iAirline]?.trim())
  .map((c) => [c[iAirline].trim(), c[iAirlineName].trim()])
  .sort((a, b) => a[0].localeCompare(b[0]));
writeFileSync(
  new URL("../src/lib/airlines-data.ts", import.meta.url),
  `// Generated by scripts/gen-airports.mjs from data/airlines.csv. Do not edit.\n` +
    `/** IATA airline code to the airline's name. */\n` +
    `export const AIRLINE_NAMES: Record<string, string> = {${carriers.map(([code, name]) => `${code}:${JSON.stringify(name)}`).join(",")}};\n`,
);
console.log(`wrote ${carriers.length} airlines`);
